'use client';

import { useState, useEffect } from 'react';
import { use } from 'react';
import { User, Mail, Building, GraduationCap, Briefcase, Linkedin, Award, MessageCircle, Loader2 } from 'lucide-react';
import { db } from '@/lib/db';
import { useAuth } from '@/contexts/AuthContext';
import { useRouter } from 'next/navigation';

interface UserProfile {
  id: string;
  email: string;
  full_name: string;
  role: string;
  department?: string;
  branch?: string;
  batch?: string;
  enrollment_number?: string;
  designation?: string;
  current_organization?: string;
  bio?: string;
  linkedin_url?: string;
  profile_picture_url?: string;
  is_verified?: boolean;
}

interface UserPosition {
  id: string;
  title: string;
  por_type: string;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  organization?: any;
}

export default function UserProfilePage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = use(params);
  const { user: currentUser } = useAuth();
  const router = useRouter();
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [positions, setPositions] = useState<UserPosition[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => { fetchProfile(); }, [id]); // eslint-disable-line react-hooks/exhaustive-deps

  async function fetchProfile() {
    const { data: profileData } = await db.from('users').select('*').eq('id', id).single();
    if (!profileData) { setLoading(false); return; }
    setProfile(profileData);
    const { data: posData } = await db
      .from('user_positions')
      .select('id, title, por_type, organization:organizations(name, slug)')
      .eq('user_id', id)
      .eq('is_active', true);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    setPositions((posData || []) as any);
    setLoading(false);
  }

  function getInitials(name?: string) {
    return name?.split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2) || '?';
  }

  async function startConversation() {
    if (!currentUser || !profile) return;
    const { data: existing } = await db.from('conversations').select('id').or(`and(participant1_id.eq.${currentUser.id},participant2_id.eq.${profile.id}),and(participant1_id.eq.${profile.id},participant2_id.eq.${currentUser.id})`).maybeSingle();
    if (existing) {
      router.push('/messages');
      return;
    }
    await db.from('conversations').insert({ participant1_id: currentUser.id, participant2_id: profile.id });
    router.push('/messages');
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 size={36} className="animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (!profile) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <User size={48} className="mx-auto mb-4 text-muted-foreground/40" />
          <h3 className="font-semibold">User Not Found</h3>
          <p className="text-sm text-muted-foreground">This user doesn&apos;t exist or has been removed.</p>
        </div>
      </div>
    );
  }

  const isOwnProfile = currentUser?.id === profile.id;

  return (
    <div className="max-w-2xl mx-auto space-y-5">
      {/* Profile Header */}
      <div className="bg-card border border-border rounded-xl p-6">
        <div className="flex items-start gap-5">
          <div className="w-20 h-20 rounded-full bg-muted flex items-center justify-center text-2xl font-bold overflow-hidden flex-shrink-0 border-2 border-border">
            {profile.profile_picture_url
              ? <img src={profile.profile_picture_url} alt={profile.full_name} className="w-full h-full object-cover" />
              : getInitials(profile.full_name)}
          </div>
          <div className="flex-1">
            <h1 className="font-bold text-xl mb-1">{profile.full_name}</h1>
            <div className="flex flex-wrap gap-2 mb-2">
              <span className="bg-amber-100 dark:bg-amber-500/20 text-amber-700 dark:text-amber-400 text-xs font-medium px-2.5 py-1 rounded-full capitalize">{profile.role}</span>
              {profile.department && <span className="bg-blue-100 dark:bg-blue-500/20 text-blue-700 dark:text-blue-400 text-xs font-medium px-2.5 py-1 rounded-full">{profile.department}</span>}
              {profile.branch && <span className="bg-purple-100 dark:bg-purple-500/20 text-purple-700 dark:text-purple-400 text-xs font-medium px-2.5 py-1 rounded-full">{profile.branch}</span>}
              {profile.is_verified && <span className="bg-green-100 dark:bg-green-500/20 text-green-700 dark:text-green-400 text-xs font-medium px-2.5 py-1 rounded-full">Verified</span>}
            </div>
            {profile.bio && <p className="text-sm text-muted-foreground leading-relaxed">{profile.bio}</p>}
          </div>
        </div>

        {!isOwnProfile && currentUser && (
          <div className="mt-4 pt-4 border-t border-border">
            <button
              className="flex items-center gap-2 bg-amber-500 hover:bg-amber-600 text-white text-sm font-medium px-4 py-2 rounded-lg transition-colors"
              onClick={startConversation}
            >
              <MessageCircle size={15} /> Send Message
            </button>
          </div>
        )}
      </div>

      {/* Details */}
      <div className="bg-card border border-border rounded-xl p-5">
        <h2 className="font-semibold mb-4">Details</h2>
        <div className="space-y-3">
          {[
            { icon: Mail, label: 'Email', value: profile.email },
            { icon: Building, label: 'Department', value: profile.department },
            { icon: GraduationCap, label: 'Branch', value: profile.branch },
            { icon: GraduationCap, label: 'Batch', value: profile.batch },
            { icon: GraduationCap, label: 'Enrollment', value: profile.enrollment_number },
            { icon: Briefcase, label: 'Designation', value: profile.designation },
            { icon: Building, label: 'Organization', value: profile.current_organization },
          ].filter(r => r.value).map(({ icon: Icon, label, value }) => (
            <div key={label} className="flex items-center gap-3">
              <Icon size={15} className="text-muted-foreground flex-shrink-0" />
              <div>
                <p className="text-xs text-muted-foreground">{label}</p>
                <p className="text-sm text-foreground">{value}</p>
              </div>
            </div>
          ))}
          {profile.linkedin_url && (
            <div className="flex items-center gap-3">
              <Linkedin size={15} className="text-muted-foreground flex-shrink-0" />
              <div>
                <p className="text-xs text-muted-foreground">LinkedIn</p>
                <a href={profile.linkedin_url} target="_blank" rel="noopener noreferrer" className="text-sm text-amber-500 hover:underline truncate">{profile.linkedin_url}</a>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Positions */}
      {positions.length > 0 && (
        <div className="bg-card border border-border rounded-xl p-5">
          <h2 className="font-semibold mb-3">Positions of Responsibility</h2>
          <div className="space-y-2">
            {positions.map(pos => (
              <div key={pos.id} className="flex items-center gap-2.5 p-3 bg-muted rounded-lg">
                <Award size={15} className="text-amber-500 flex-shrink-0" />
                <div>
                  <p className="text-sm font-medium text-foreground">{pos.title}</p>
                  {pos.organization && <p className="text-xs text-muted-foreground">{pos.organization.name}</p>}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}
